export const CLASSIC_TIMINGS=Object.freeze({openDuration:276,openFadeDuration:38,openChildFadeDuration:76,closeDuration:200,closeFadeDuration:50,closeChildFadeDuration:140}),U_TIMINGS=Object.freeze({openDuration:200,openFadeDuration:83,openChildFadeDuration:83,closeDuration:233,closeChildFadeStartDelay:150,openOvershootDuration:200}),SHORTCUT_COLLAPSE_THRESHOLD=6;export function popupTimings(o){return o?U_TIMINGS:CLASSIC_TIMINGS}export function foldShortcuts(o,n=SHORTCUT_COLLAPSE_THRESHOLD){const e=Array.isArray(o)?o.filter(Boolean):[];return{visible:e.slice(0,n),folded:e.slice(n),foldedCount:Math.max(0,e.length-n),hasFoldRow:e.length>n}}export function openSchedule(o,n){const e=popupTimings(o),r=e.openChildFadeDuration,t=[];for(let a=0;a<n;a++)t.push({index:a,delay:a*r,duration:e.openChildFadeDuration});return{container:{fade:e.openFadeDuration,settle:e.openDuration,overshoot:e.openOvershootDuration},children:t}}export function closeSchedule(o,n){const e=popupTimings(o),r=[];for(let t=0;t<n;t++)r.push({index:t,delay:e.closeChildFadeStartDelay,duration:e.openChildFadeDuration});return{container:{fade:e.closeDuration},children:r}}
